package com.afirma.assina;
import java.util.*;
/** Formatação dos botões reply e listas implementados na API Meta da origem. */
public final class MensagensInterativasAutentica {
 private MensagensInterativasAutentica(){}
 public static Map<String,Object> montar(Map<String,Object> m){String tipo=Objects.toString(m.get("Tipo"),"").toLowerCase(Locale.ROOT);RegrasAutentica.exigir(tipo.equals("botao")||tipo.equals("lista"),"Tipo de mensagem interativa inválido");String texto=Objects.toString(m.getOrDefault("Texto",m.get("MensagemTexto")),"");RegrasAutentica.exigir(!texto.isBlank()&&texto.length()<=1024,"Texto da mensagem interativa inválido");var r=new LinkedHashMap<String,Object>(Map.of("type",tipo.equals("botao")?"button":"list","body",Map.of("text",texto)));if(m.get("Rodape") instanceof String f&&!f.isBlank()){RegrasAutentica.exigir(f.length()<=60,"Rodapé muito longo");r.put("footer",Map.of("text",f));}
  if(tipo.equals("botao")){RegrasAutentica.exigir(m.get("Botoes") instanceof List<?>,"Informe os botões");var botoes=(List<?>)m.get("Botoes");RegrasAutentica.exigir(!botoes.isEmpty()&&botoes.size()<=3,"Informe de 1 a 3 botões reply");var bs=new ArrayList<Object>();for(var b:botoes){RegrasAutentica.exigir(b instanceof Map<?,?>,"Botão inválido");var v=(Map<?,?>)b;RegrasAutentica.exigir("reply".equals(v.get("Tipo")),"Tipo de botão não suportado");bs.add(Map.of("type","reply","reply",Map.of("id",campo(v,"Id",256),"title",campo(v,"Texto",20))));}r.put("action",Map.of("buttons",bs));}
  else{RegrasAutentica.exigir(m.get("Lista") instanceof Map<?,?>,"Informe a lista");var lista=(Map<?,?>)m.get("Lista");RegrasAutentica.exigir(lista.get("Itens") instanceof List<?>,"Informe os itens da lista");var secoes=new ArrayList<Object>();int total=0;for(var s:(List<?>)lista.get("Itens")){RegrasAutentica.exigir(s instanceof Map<?,?>,"Seção inválida");var secao=(Map<?,?>)s;RegrasAutentica.exigir(secao.get("Itens") instanceof List<?>,"Itens inválidos");var linhas=new ArrayList<Object>();for(var v:(List<?>)secao.get("Itens")){RegrasAutentica.exigir(v instanceof Map<?,?>,"Item inválido");var item=(Map<?,?>)v;var row=new HashMap<String,Object>(Map.of("id",campo(item,"Id",200),"title",campo(item,"Titulo",24)));if(item.get("Descricao") instanceof String descricao&&!descricao.isBlank())row.put("description",campo(item,"Descricao",72));linhas.add(row);total++;}secoes.add(Map.of("title",campo(secao,"Titulo",24),"rows",linhas));}RegrasAutentica.exigir(total>0&&total<=10,"Informe de 1 a 10 itens na lista");r.put("action",Map.of("button",campo(lista,"Texto",20),"sections",secoes));}return r;
 }
 private static String campo(Map<?,?> v,String nome,int max){String s=Objects.toString(v.get(nome),"");RegrasAutentica.exigir(!s.isBlank()&&s.length()<=max,"Conteúdo inválido em "+nome);return s;}
}
